#!/bin/bash
# C7 final (F1 = 20261120140000, F2 = 20261120150000): review-only candidate apply files.
# Not the C6 internal stage C7 (20261110090000, docs/reviews/c6-apply/C7.sql).
#
#   BUNDLE_C7_FINAL.sql  F1 then F2 in ONE transaction, to run AFTER BUNDLE_C1_C10.sql has committed.
#                        Generated by docs/reviews/c6-apply/make_stage_c6.py (unchanged): every block checks
#                        the exact ledger versions AND content (production's 52 + C1..C10, then + F1).
#                        Any failure, including between F1 and F2, leaves the database exactly at 62.
#   VERIFY_C7_FINAL.sql  read-only: 64 rows, both ledger fingerprints, both F rows' content, and for the
#                        three functions F1/F2 redefine: exact body, SECURITY DEFINER, search_path, owner,
#                        and EXECUTE for authenticated only among the client roles.
#
# Sources and constants (no new fingerprint source):
#   - base ledger: docs/reviews/c6-ledger/prod_ledger_2026-11-16.txt (sha256 pinned below; matched in production
#     on 2026-11-22, #97 comment 7082696468)
#   - C1..C10: read from 183dc50, exactly as docs/reviews/c6-apply/build_apply_files.sh does
#   - F1/F2: the committed migrations, sha256 pinned from docs/reviews/c6-package/C6_C7_RELEASE_LEDGER_RECEIPT.md
#   - with the production base, the computed 62/64 fingerprints must equal that receipt's offline expectations
#
# usage: build_c7_final.sh <repo-root> [EXPECTED_LEDGER_FILE OUT_DIR]   (the optional pair = lab test build)
set -euo pipefail
R=$1; D=${3:-$R/docs/reviews/c7-final}; G=$R/docs/reviews/c6-apply; T=$(mktemp -d); mkdir -p "$D"
trap 'rm -rf "$T"' EXIT
PROD_BASE=$R/docs/reviews/c6-ledger/prod_ledger_2026-11-16.txt
BASE=${2:-$PROD_BASE}
echo "277292ef2e84ed7c0a2d33c0f8217d2810526a27ee849bea0b391e7ff8f4abae  $PROD_BASE" | sha256sum -c --quiet
echo "7ca2de5e257c0f2ffd278a914fb316926ee1bd675b9e5da8324a2876bd89457b  $G/make_stage_c6.py" | sha256sum -c --quiet
M=(20260815170000_fin_courier_pr_a 20260815171000_fin_idem_sale_create 20261028213608_fractional_quantity_01
   20261029044024_c3_reconcile_financial_adapters 20261103060658_c5_keyed_debt_collection
   20261106145346_c5_day_close_profit_report 20261110090000_courier_settle_custody_01
   20261110130000_paddle_webhook_no_key_update_01 20261110140000_tenants_narrow_client_grants_01
   20261110150000_defpriv_function_execute_01)
prior=""
for m in "${M[@]}"; do
  git -C "$R" show "183dc50:supabase/migrations/$m.sql" > "$T/$m.sql"
  prior="${prior:+$prior,}${m:0:14}:$(md5sum < "$T/$m.sql" | cut -c1-32)"
done
F1=$R/supabase/migrations/20261120140000_guard_courier_custody_settlement.sql
F2=$R/supabase/migrations/20261120150000_close_day_courier_debt_balance.sql
printf '%s  %s\n' e14b9f03582b79b83e4334bb8c8ae32eb2ecde6e0669c20a872cb74060e0a2a7 "$F1" \
                  4f48a50379a0a215d52069f0062049c833b4d255e35ea65ec4370e1bdeacf8a5 "$F2" | sha256sum -c --quiet
{
  echo "-- C7 final bundle (F1 = 20261120140000, then F2 = 20261120150000). Review-only candidate; not approved for any target."
  echo "-- ONE transaction. Run as postgres only after BUNDLE_C1_C10.sql has committed and VERIFY shows 62 rows."
  echo "-- Each block checks the exact ledger versions and content; any failure leaves the database exactly at 62."
  echo "-- Not the C6 internal stage C7 (20261110090000). Legacy sale/collection grants are not touched."
  echo "BEGIN;"
  python3 "$G/make_stage_c6.py" "C7F" --base-ledger "$BASE" --prior "$prior" "$F1" "$F2"
  echo "COMMIT;"
} > "$D/BUNDLE_C7_FINAL.sql"
python3 - "$BASE" "$PROD_BASE" "$prior" "$F1" "$F2" "$D/VERIFY_C7_FINAL.sql" <<'PY'
import hashlib, re, sys
base_file, prod_file, prior, f1, f2, out = sys.argv[1:7]
def ledger(path):
    return [tuple(l.split()[:2]) for l in open(path) if l.strip()]
prior = [tuple(x.split(':')) for x in prior.split(',')]
fs = [(p.split('/')[-1][:14], hashlib.md5(open(p, 'rb').read()).hexdigest()) for p in (f1, f2)]
def fp(rows):
    rows = sorted(rows)
    return (len(rows), hashlib.md5(','.join(v for v, _ in rows).encode()).hexdigest(),
            hashlib.md5(','.join(f'{v}:{m}' for v, m in rows).encode()).hexdigest())
# Production expectations recorded in C6_C7_RELEASE_LEDGER_RECEIPT.md (offline, same algorithm as the guard).
prod = ledger(prod_file)
assert fp(prod) == (52, '9235c3834be88ce50dba444bb15b5262', 'a3de2f506b1da505ae41c9fd553c87d7'), fp(prod)
assert fp(prod + prior) == (62, '8eec91642011d297ca5504cebda430ef', '1e6c4c7ce50bf9c8f9526de2888df919'), fp(prod + prior)
assert fp(prod + prior + fs) == (64, 'a6ca71705682237fc4bc6b93c4f782b5', '1c671404c3969bc09f451c3cea7b608b'), fp(prod + prior + fs)
n, vmd5, cmd5 = fp(ledger(base_file) + prior + fs)
# Exact function bodies (pg_proc.prosrc) as written between the dollar quotes of F1/F2.
def bodies(path):
    text = open(path, encoding='utf-8').read()
    found = {}
    for m in re.finditer(r'CREATE OR REPLACE FUNCTION public\.(\w+)\(.*?\bAS\s+(\$\w*\$)(.*?)\2', text, re.S):
        found[m.group(1)] = hashlib.md5(m.group(3).encode()).hexdigest()
    return found
b = {**bodies(f1), **bodies(f2)}
assert sorted(b) == ['close_day', 'settle_courier_orders', 'update_courier_outcome_v2'], sorted(b)
sig = {'update_courier_outcome_v2': 'public.update_courier_outcome_v2(uuid,public.courier_state,numeric,uuid)',
       'settle_courier_orders': 'public.settle_courier_orders(uuid,uuid[])',
       'close_day': 'public.close_day(text)'}
checks = []
for name in ('update_courier_outcome_v2', 'settle_courier_orders', 'close_day'):
    s = sig[name]
    checks.append(f"""  '{name}', (select json_build_object(
      'body_ok', md5(p.prosrc) = '{b[name]}',
      'security_definer', p.prosecdef,
      'search_path_public', p.proconfig = array['search_path=public'],
      'owner_postgres', pg_get_userbyid(p.proowner) = 'postgres',
      'authenticated_execute', has_function_privilege('authenticated', p.oid, 'EXECUTE'),
      'anon_no_execute', not has_function_privilege('anon', p.oid, 'EXECUTE'),
      'public_no_execute', not coalesce((select bool_or(a.grantee = 0) from aclexplode(p.proacl) a where a.privilege_type = 'EXECUTE'), false))
    from pg_proc p where p.oid = to_regprocedure('{s}'))""")
label = 'production' if base_file == prod_file else 'TEST base ' + base_file.split('/')[-1]
open(out, 'w').write(f"""-- C7 final read-only verification ({label} ledger constants). Review-only candidate.
-- Expected after BUNDLE_C1_C10.sql then BUNDLE_C7_FINAL.sql: every *_ok and every function field true.
-- Ledger fingerprints use the same expressions as the bundle guard and PRECHECK_target_ledger_read.sql.
begin transaction read only;
select json_build_object(
  'ro', current_setting('transaction_read_only'),
  'ledger_rows', (select count(*) from supabase_migrations.schema_migrations),
  'ledger_rows_ok', (select count(*) from supabase_migrations.schema_migrations) = {n},
  'ledger_versions_ok', (select md5(coalesce(string_agg(version, ',' ORDER BY version), '')) from supabase_migrations.schema_migrations) = '{vmd5}',
  'ledger_content_ok', (select md5(string_agg(version || ':' || coalesce(md5(array_to_string(statements, E'\\n')), '-'), ',' ORDER BY version)) from supabase_migrations.schema_migrations) = '{cmd5}',
  'f1_content_ok', (select md5(array_to_string(statements, E'\\n')) from supabase_migrations.schema_migrations where version = '{fs[0][0]}') = '{fs[0][1]}',
  'f2_content_ok', (select md5(array_to_string(statements, E'\\n')) from supabase_migrations.schema_migrations where version = '{fs[1][0]}') = '{fs[1][1]}',
  'functions', json_build_object(
{(','+chr(10)).join(checks)})
) as c7_final_verify;
rollback;
""")
print(f'VERIFY constants ({label}): rows {n}, versions {vmd5}, content {cmd5}')

# STOP_RESUME.md section 2: the 62-row checkpoint after BUNDLE_C1_C10.sql (C6 committed, F not applied).
# Every expectation below is derived from the pinned C6 sources (183dc50); only the ledger constants
# depend on the base ledger (production or a lab test base).
n62, v62, c62 = fp(ledger(base_file) + prior)
if base_file == prod_file:
    assert (n62, v62, c62) == (62, '8eec91642011d297ca5504cebda430ef', '1e6c4c7ce50bf9c8f9526de2888df919')
LEGACY = {  # withdrawn from client roles by C2/C4 (sale) and C5 (collection)
    'legacy_sale': 'public.create_sale_with_items(uuid,public.delivery_kind,uuid,numeric,public.payment_method,jsonb)',
    'legacy_sale_v2': 'public.create_sale_with_items_v2(uuid,public.delivery_kind,uuid,numeric,public.payment_method,jsonb,public.courier_state)',
    'legacy_collection': 'public.collect_order_debt(uuid,numeric,public.payment_method)',
}
KEYED = {  # granted to authenticated only by C2/C4 (sale) and C5 (collection)
    'keyed_sale': 'public.create_sale_with_items_idempotent(uuid,uuid,public.delivery_kind,uuid,numeric,public.payment_method,jsonb,public.courier_state)',
    'keyed_collection': 'public.collect_order_debt_idempotent(uuid,uuid,numeric,public.payment_method)',
}
def pub_exec(expr):
    return f"exists(select 1 from aclexplode(coalesce((select proacl from pg_proc where oid = {expr}), acldefault('f', (select proowner from pg_proc where oid = {expr})))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE')"
rows = [
    ('ledger_rows_ok', f"(select count(*) from supabase_migrations.schema_migrations) = {n62}"),
    ('ledger_versions_ok', f"(select md5(coalesce(string_agg(version, ',' ORDER BY version), '')) from supabase_migrations.schema_migrations) = '{v62}'"),
    ('ledger_content_ok', f"(select md5(string_agg(version || ':' || coalesce(md5(array_to_string(statements, E'\\n')), '-'), ',' ORDER BY version)) from supabase_migrations.schema_migrations) = '{c62}'"),
]
for v, m in prior:
    rows.append((f'c6_{v}_content_ok', f"(select md5(array_to_string(statements, E'\\n')) from supabase_migrations.schema_migrations where version = '{v}') = '{m}'"))
for name, sig in LEGACY.items():
    o = f"to_regprocedure('{sig}')"
    rows += [(f'{name}_exists', f"{o} is not null"),
             (f'{name}_authenticated_withdrawn', f"not has_function_privilege('authenticated', {o}, 'EXECUTE')"),
             (f'{name}_anon_withdrawn', f"not has_function_privilege('anon', {o}, 'EXECUTE')"),
             (f'{name}_public_withdrawn', f"{o} is not null and not {pub_exec(o)}")]
for name, sig in KEYED.items():
    o = f"to_regprocedure('{sig}')"
    rows += [(f'{name}_exists', f"{o} is not null"),
             (f'{name}_authenticated_execute', f"has_function_privilege('authenticated', {o}, 'EXECUTE')"),
             (f'{name}_anon_withdrawn', f"not has_function_privilege('anon', {o}, 'EXECUTE')"),
             (f'{name}_public_withdrawn', f"{o} is not null and not {pub_exec(o)}")]
view = "to_regclass('public.day_close_profit_report')"
rows += [('report_view_is_view', f"(select relkind from pg_class where oid = {view}) = 'v'"),
         ('report_view_security_invoker', f"(select 'security_invoker=true' = any(coalesce(reloptions, '{{}}')) from pg_class where oid = {view})"),
         ('report_view_authenticated_select', f"has_table_privilege('authenticated', {view}, 'SELECT')"),
         ('report_view_anon_no_select', f"not has_any_column_privilege('anon', {view}, 'SELECT')")]
values = ',\n'.join(f"  ('{k}', coalesce(({e}), false))" for k, e in rows)
open(out.replace('VERIFY_C7_FINAL.sql', 'VERIFY_C6_CHECKPOINT.sql'), 'w').write(f"""-- C6 checkpoint (62 rows: C6 committed, F1/F2 not applied) read-only verification ({label} ledger constants).
-- Review-only candidate. STOP_RESUME.md section 2. Continue only if "ok" is literally true.
-- A missing object or a NULL result makes its check false (coalesce), so "ok" is false; "checks" must equal {len(rows)}.
-- No catalog-wide fingerprint: none has an approved production reference (pending).
begin transaction read only;
with c(name, ok) as (values
{values}
)
select json_build_object(
  'ro', current_setting('transaction_read_only'),
  'checks', (select count(*) from c),
  'ok', (select bool_and(ok) from c) and (select count(*) from c) = {len(rows)},
  'failed', (select coalesce(json_agg(name order by name), '[]'::json) from c where not ok)
) as c6_checkpoint_verify;
rollback;
""")
print(f'C6 checkpoint constants ({label}): rows {n62}, versions {v62}, content {c62}; {len(rows)} checks')
PY
echo "built in $D: BUNDLE_C7_FINAL.sql, VERIFY_C7_FINAL.sql, VERIFY_C6_CHECKPOINT.sql (expected ledger: $BASE)"
